5	6	handler	rust	pub async fn login(mut request: Request) -> AppResult<Response> {\n    let form: LoginForm = request.form();\n    let validated = match ValidationForm::try_new(form, &request).await {\n        Ok(validated) => validated,\n        Err(form) => {\n            context_update!(request => { "login_form" => &form });\n            return request.render("auth/login.html");\n        }\n    };\n    let username = validated.cleaned_string("username").unwrap_or_default();\n    let password = validated.cleaned_string("password").unwrap_or_default();\n\n    // Checks the password even for an unknown username (no timing difference)\n    // and refuses inactive or not yet activated accounts.\n    if let Some(user) = authenticate_user(&request.engine.db, &username, &password).await {\n        auth_login(&request.session, &request.engine.db, user.id).await.ok();\n        return Ok(Redirect::to("/profile").into_response());\n    }\n    context_update!(request => {\n        "login_form" => &*validated,\n        "messages"   => flash_now!(error => "Invalid credentials"),\n    });\n    request.render("auth/login.html")\n}	handler	2
