75	28	Usage in the login handler	rust	pub async fn login(\n    State(guard): State<Arc<LoginGuard>>,  // State before Request\n    mut request: Request,\n) -> AppResult<Response> {\n    let form: LoginForm = request.form();\n    let username = form.cleaned_string("username").unwrap_or_default();\n    // Keyed by username: locks the targeted account, whatever the IP\n    let key = LoginGuard::effective_key(&username, "unknown");\n\n    if guard.is_locked(&key) {\n        if let Some(secs) = guard.remaining_lockout_secs(&key) {\n            warning!(request.notices => format!("Account locked. Try again in {secs}s."));\n        }\n        context_update!(request => { "login_form" => &form });\n        return request.render("auth/login.html");\n    }\n\n    let validated = match ValidationForm::try_new(form, &request).await {\n        Ok(validated) => validated,\n        Err(form) => {\n            context_update!(request => { "login_form" => &form });\n            return request.render("auth/login.html");\n        }\n    };\n    let password = validated.cleaned_string("password").unwrap_or_default();\n    let db = &request.engine.db;\n    match authenticate_user(db, &username, &password).await {\n        Some(user) => {\n            guard.record_success(&key);\n            auth_login(&request.session, db, user.id).await.ok();\n            return Ok(Redirect::to("/profile").into_response());\n        }\n        None => {\n            guard.record_failure(&key);\n            error!(request.notices => "Incorrect credentials.");\n        }\n    }\n    context_update!(request => { "login_form" => &*validated });\n    request.render("auth/login.html")\n}\n\n// The admin has its own: .with_admin(|a| a.with_login_guard(LoginGuard::new()))	handler	2
