-- Content of the demo site. Running it empties the content tables, then
-- fills them again: safe to replay after every change.
--
-- Run at every start by demo-app (backend/seeds/demo.rs). All the emptying
-- happens here, in the same transaction as the reload: a failing seed leaves
-- the current content in place.
--
-- changelog_entry and roadmap_entry are left out on purpose: they are edited
-- in production through the admin, the seed must never overwrite them.
-- blog is emptied too: the demo blog starts blank after each restart.

BEGIN;

TRUNCATE demo_section, form_field, page_doc_link, code_example, demo_page,
         demo_category, known_issue, blog;

-- Enum types (not generated by migrations — required for fresh installs)
DO $$ BEGIN
    CREATE TYPE courblocktype AS ENUM ('code', 'text', 'table', 'list', 'warning');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
    CREATE TYPE courtheme AS ENUM ('Fondamentaux', 'Mémoire & sûreté', 'Indispensables', 'Avancé', 'Runique');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
    CREATE TYPE difficulte AS ENUM ('debutant', 'intermediaire', 'avance', 'specifique');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
    CREATE TYPE pagetype AS ENUM ('code', 'form', 'custom', 'doc_en', 'doc_fr');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;











-- Resync sequences after explicit-ID inserts
SELECT setval(pg_get_serial_sequence('demo_category', 'id'), (SELECT MAX(id) FROM demo_category));
SELECT setval(pg_get_serial_sequence('demo_page', 'id'), (SELECT MAX(id) FROM demo_page));
SELECT setval(pg_get_serial_sequence('demo_section', 'id'), (SELECT MAX(id) FROM demo_section));
SELECT setval(pg_get_serial_sequence('form_field', 'id'), (SELECT MAX(id) FROM form_field));
SELECT setval(pg_get_serial_sequence('page_doc_link', 'id'), (SELECT MAX(id) FROM page_doc_link));
SELECT setval(pg_get_serial_sequence('blog', 'id'), (SELECT MAX(id) FROM blog));
SELECT setval(pg_get_serial_sequence('known_issue', 'id'), (SELECT MAX(id) FROM known_issue));
SELECT setval(pg_get_serial_sequence('code_example', 'id'), (SELECT MAX(id) FROM code_example));

COMMIT;
